<?php get_header(); ?><div class="container catalogue-layout"><div class="page-head"><span class="eyebrow">Project catalogue</span><h1>Find your next great project.</h1><p>Search by project, technology or component.</p></div><form class="toolbar" method="get" action="<?php echo esc_url(get_post_type_archive_link('classs_project')); ?>"><input name="s" value="<?php echo esc_attr(get_search_query()); ?>" placeholder="Search projects" aria-label="Search projects"><input type="hidden" name="post_type" value="classs_project"><?php foreach(['branch'=>['CSE','ECE','EEE','Mechanical'],'difficulty'=>['Beginner','Intermediate','Advanced'],'technology'=>['ESP32','Arduino','Python','Robotics','CAD']] as $key=>$vals): ?><select name="<?php echo esc_attr($key); ?>" aria-label="<?php echo esc_attr($key); ?>"><option value="">All <?php echo esc_html($key); ?></option><?php foreach($vals as $v) echo '<option value="'.esc_attr($v).'" '.selected(isset($_GET[$key])?sanitize_text_field(wp_unslash($_GET[$key])):'',$v,false).'>'.esc_html($v).'</option>'; ?></select><?php endforeach; ?><button class="btn blue">Find projects</button></form><div class="grid"><?php if(have_posts()) while(have_posts()) { the_post(); classs_project_card(get_the_ID()); } else echo '<p>No projects match your search.</p>'; ?></div><?php the_posts_pagination(); ?></div><?php get_footer(); ?>
